// Har lead ke liye is baar ka nurture step number nikaalo taaki Ollama ko content-type bataya ja sake
const step = $json.nurture_step || 0;
const stepThemes = {
  0: 'share a genuinely useful tip or mini case study related to their service interest, no pitch',
  1: 'share a relevant client success story/result with a soft call to action to book a quick call',
  2: 'a friendly last check-in, ask if priorities changed, offer a small no-obligation audit/consultation'
};
return [{
  json: {
    ...$json,
    nurture_step: step,
    step_theme: stepThemes[step] || stepThemes[2]
  }
}];

