={
  "model": "qwen2.5:7b",
  "stream": false,
  "prompt": "You are writing a nurture-sequence message for a digital agency (Nivy International). This is drip step {{$json.nurture_step + 1}} of 3.

Lead name: {{$json.name}}
Company: {{$json.company}}
Service interest: {{$json.service_type}}
Goal for this message: {{$json.step_theme}}

Return ONLY a valid JSON object with exactly these keys: email_subject (under 60 chars), email_body (100-150 words, plain text, warm and low-pressure tone), whatsapp_message (under 250 chars, casual)."
}

parameters.jsCode:
const response = $input.item.json.response || '';
let parsed = {};
try {
  parsed = JSON.parse(response);
} catch (e) {
  const match = response.match(/\{[\s\S]*\}/);
  parsed = match ? JSON.parse(match[0]) : { email_subject: '', email_body: '', whatsapp_message: '' };
}
const lead = $('Compute Step Theme').item.json;
return [{
  json: {
    odoo_lead_id: lead.odoo_lead_id,
    name: lead.name,
    email: lead.email,
    phone: lead.phone,
    nurture_step: lead.nurture_step,
    email_subject: parsed.email_subject || 'Quick thought for you',
    email_body: parsed.email_body || '',
    whatsapp_message: parsed.whatsapp_message || ''
  }
}];

